export function applicationContent(fields, snapshot, { selection, labProjectId } = {}) {
  const project = industrialProjects.find(p => p.id === labProjectId);
  const prefix = selection ? `课程项目选题：${selection.semesterLabel}；选定后已开放对应章节，无需等待审批。

` : project ? `实验室项目：${project.title}
官网介绍：${project.url}

` : '';
  return prefix + [['姓名', fields.name], ['学校/专业/年级', fields.school], ['学生提供的课程成绩', fields.academicResults], ['个人介绍', fields.introduction], ['技能与项目经历', fields.experience], ['意向项目', fields.project], ['每周可投入时间', fields.availability], ['平台学习记录', learningSummary(snapshot)], ['记录时间', snapshot.capturedAt], ['成绩说明', '平台作业尚无统一数值评分；已提交、助教点评和结业通过分别记录。学生自述成绩及附件待老师核查。']].map(([label, value]) => `${label}：${value}`).join('

');

if (!exactKeys(data, ['operation', 'email', 'applicationId', 'submissionKey', 'fields', 'files', 'learning', 'content', 'confirmed', 'kind', 'selection', 'labProjectId']) || data.operation !== 'submit' || data.confirmed !== true) applicationError('申请格式不正确。');
const kind = data.kind || 'lab_application';
if (!['lab_application', 'course_project_selection'].includes(kind)) applicationError('项目类型不正确。');
const isSelection = kind === 'course_project_selection';
const id = applicationId(data.applicationId), submissionKey = applicationId(data.submissionKey), fields = validateApplicationFields(data.fields), files = validateApplicationFiles(data.files || []), learning = validateSnapshot(data.learning, !isSelection);
let selection, labProjectId;
if (isSelection) {
  const value = data.selection, semester = academicSemester(Date.parse(learning.capturedAt));
  const project = courseProjects.find(p => p.id === value?.courseId);
  if (!exactKeys(value, ['courseId','semesterId','semesterLabel']) || !project || value.semesterId !== semester.id || value.semesterLabel !== semester.label || fields.project !== project.title || files.length || data.labProjectId) applicationError('课程项目与学期信息不正确。');
  selection = { courseId: project.id, semesterId: semester.id, semesterLabel: semester.label };
  await db.prepare('CREATE TABLE IF NOT EXISTS project_course_selection_claims(email TEXT NOT NULL COLLATE NOCASE,semester_id TEXT NOT NULL,application_id TEXT NOT NULL UNIQUE,PRIMARY KEY(email,semester_id))').run();
  const reserved = await db.prepare('SELECT application_id FROM project_course_selection_claims WHERE email=? AND semester_id=?').bind(email, semester.id).first();
  if (reserved && reserved.application_id !== id) applicationError('本学期的课程项目已提交，每学期只能选择一个。', 409);
} else {
  if (data.selection) applicationError('实验室申请格式不正确。');
  const project = industrialProjects.find(p => p.id === data.labProjectId);
  if (data.kind && (!project || fields.project !== project.title)) applicationError('请从官网三个工业项目中选择意向项目。');
  labProjectId = project?.id;
}
const content = applicationContent(fields, learning, { selection, labProjectId });

const body = { circulationContent: content, circulationRecipients: [], circulationApprovers: [approver], circulationConfirmations: [], circulationApprovals: [], initialReviewerEmail: reviewer.email, initialReviewerName: reviewer.name, workflowMutationRevision: mutation, projectApplication: { version: APPLICATION_VERSION, kind, ...(selection ? { selection } : {}), ...(labProjectId ? { labProjectId } : {}), source: 'learning_tutor', email, fields, learning, files: attachments, historicalFiles, submissionKey, requestHash, confirmedAt: at, identityNote: '登录邮箱由学习系统验证；姓名、成绩及项目经历由学生提供，待老师核查。' } };
const row = { id, type: '流转审批', title: `${isSelection ? '课程选题' : '实验室报名'} · ${fields.name} · ${fields.project}`.slice(0, 160), project: isSelection ? 'OriginMind 课程项目选题' : 'OriginMind × ARTS Robotics 实验室报名', requesterName: fields.name, requesterEmail: email, clientCreationKey: old?.client_creation_key || `learning-project:${id}`, businessKey: isSelection ? `learning-course:${await applicationHash(email+'|'+selection.semesterId)}` : null, createdAt: old?.created_at || at, updatedAt: at, status: '待审核', currentStep: '指定审批', currentReviewerName: reviewer.name, currentReviewerEmail: reviewer.email, summary: `${selection ? selection.semesterLabel + ' · 已开放章节；' : '意向：'}${fields.project}。${learningSummary(learning)}`, owner: reviewer.name, amount: null, periodKey: null, signersJson: '[]', payloadJson: JSON.stringify(body) };
const event = { actorName: fields.name, actorEmail: email, action: old ? 'resubmitted' : 'submitted', note: isSelection ? '学生已选定本学期课程项目，对应章节立即开放；通知马淦待处理。' : old ? '学生在课程助教核对补充材料并确认重新提交。' : '学生在课程助教核对报名材料并确认提交给马淦。', occurredAt: at };
